export interface McpToolMeta {
  title: string;
  titleAr: string;
  /** Role permission the client's acting role needs (null: any role). */
  permission: Permission | null;
  /** Module the tenant must be entitled to (in addition to `mcp`). */
  module: ModuleKey;
  /** Sensitive tools never execute directly: they create an approval request. */
  sensitive: boolean;
  /** Read-only tools never change state. */
  readOnly: boolean;
  /** Per-tool, per-client limit (calls per minute), on top of the client limit. */
  ratePerMin: number;
  /**
   * 21-MCP: the tool proposes a change set. The restaurant's approval policy (change_policies, made stricter per
   * connection) decides whether it applies at once, waits for a person or is refused; `previewOnly` shows the diff.
   */
  changeSet?: boolean;
  /** Changes or removes existing data (MCP `destructiveHint`). */
  destructive?: boolean;
}

